function personalToolbar(){return '<div class="pr2-command"><div class="pr2-menu-wrap"><button class="primary" data-pr2-menu="new">新建　⌄</button><div class="pr2-dropdown" data-pr2-dropdown="new"><button data-create="text">文本</button><button data-create="folder">文件目录</button></div></div><div class="pr2-menu-wrap"><button class="outline" data-pr2-menu="import">导入　⌄</button><div class="pr2-dropdown" data-pr2-dropdown="import"><button data-import="file">文件</button><button data-import="folder">文件夹</button></div></div><button data-selection-action data-batch-action="authorize" disabled>授权</button><button data-selection-action data-batch-action="share" disabled>共享</button><button data-selection-action data-batch-action="tag" disabled>添加标签</button><div class="pr2-menu-wrap"><button data-selection-action data-pr2-menu="batch-more" disabled>更多　⌄</button><div class="pr2-dropdown" data-pr2-dropdown="batch-more"><button data-batch-more="move">移动</button><button data-batch-more="download">下载</button><button data-batch-more="delete">删除</button></div></div><div class="pr2-command-spacer"></div><select id="pr2ShareFilter" aria-label="分享状态"><option value="all" '+(state.shareFilter==='all'?'selected':'')+'>分享状态：全部</option><option value="mine" '+(state.shareFilter==='mine'?'selected':'')+'>我分享的</option><option value="received" '+(state.shareFilter==='received'?'selected':'')+'>分享给我的</option></select><select><option>解析状态</option><option>解析成功</option><option>解析中</option></select><form id="pr2DocSearch"><input value="'+esc(state.query)+'" placeholder="请输入搜索关键字"><button>⌕</button></form><button class="refresh" data-pr2-action="refresh">↻</button></div>'}
function personalDocRow(x,index){var tags=(x.tags||[]).map(function(t){return '<em>'+esc(t)+'</em>'}).join(''),key=documentVersionKey('personal',x,index),editable=!isFeishuDocument(x);return '<div class="pr2-tr '+(editable?'':'pr2-feishu-document-row')+'"><span>'+checkbox('personal-'+index)+'</span><div class="pr2-doc-name">'+fileIcon(x.type)+'<span><span class="pr2-doc-title-line"><a href="'+docHref(x.id,'',editable,key)+'">'+esc(x.name)+'</a>'+(x.star?'<button class="pr2-star active" data-doc-star="'+index+'" title="取消收藏">★</button>':'')+((x.publicSpaces||[]).length?'<button class="pr2-public-share" data-public-spaces="'+index+'" data-tooltip="已关联公共空间">⌯</button>':'')+((x.authorizedUsers||[]).length?'<button class="pr2-auth-dot" data-authorized-users="'+index+'" data-tooltip="已授权给用户">♧</button>':'')+'</span><small>'+tags+'<button data-doc-tag="'+index+'">＋ 打标</button></small></span></div><span>'+x.type+'</span>'+documentSourceBadge(x)+'<span>'+x.updated+'</span><span class="pr2-parse '+(x.parse==='解析中'?'working':'')+'">'+x.parse+'</span><span>'+x.size+'</span><div class="pr2-row-actions dv2-list-actions">'+documentVersionActions(x,index,'personal',editable)+'<button data-doc-share="'+index+'">共享</button><button data-doc-reparse="'+index+'">重新解析</button><div class="pr2-row-menu-wrap"><button data-pr2-more="'+index+'">更多</button><div class="pr2-dropdown pr2-row-menu" data-pr2-row-menu="'+index+'"><button data-doc-authorize="'+index+'">授权</button><button data-doc-move="'+index+'">移动</button><button data-doc-unfavorite="'+index+'">取消收藏</button><button data-doc-download="'+index+'">下载</button><button class="danger" data-doc-delete="'+index+'">删除</button></div></div></div></div>'}
function personalFolderRow(name){return '<div class="pr2-tr pr2-folder-row"><span></span><div class="pr2-doc-name"><i class="pr2-file folder">夹</i><span><button class="pr2-folder-title" data-doc-folder-scope="personal" data-doc-folder-open="'+esc(name)+'"><b>'+esc(name)+'</b></button><small>'+esc(documentFolderPath(name,personalFolderParents,'个人空间'))+'</small></span></div><span>文件目录</span><span>—</span><span>刚刚</span><span>—</span><span>—</span><div class="pr2-row-actions"><button data-doc-folder-scope="personal" data-doc-folder-open="'+esc(name)+'">打开</button></div></div>'}
function personalView(){var folders=personalFolders.filter(function(name){return (personalFolderParents[name]||'')===state.personalFolder&&(!state.query||name.toLowerCase().indexOf(state.query.toLowerCase())>-1)}),rows=personalDocs.map(function(doc,index){return {doc:doc,index:index,share:index===0||index===2||index===5?'mine':index===1||index===3?'received':'none'}}).filter(function(item){var shareMatch=state.shareFilter==='all'||item.share===state.shareFilter;return documentInFolder(item.doc,state.personalFolder)&&archiveMatches(item.doc)&&shareMatch&&(!state.query||item.doc.name.toLowerCase().indexOf(state.query.toLowerCase())>-1)}),count=folders.length+rows.length;return '<section class="pr2-work"><header class="pr2-title"><div><h1>'+(state.personalFolder?esc(state.personalFolder):'个人空间')+'</h1><p>仅自己可见 · 管理个人上传与导入的文档</p></div></header>'+typeMenu()+feishuSyncBar()+'<div class="pr2-stats personal">'+stat('▥',String(personalDocs.length),'全部文档','blue')+stat('✓','7','已完成解析','green')+stat('…','1','解析中','orange')+stat('⌯','2','已授权','purple')+'</div>'+personalToolbar()+documentBreadcrumb('personal',state.personalFolder,personalFolderParents,'个人空间')+'<div class="pr2-table personal-table"><div class="pr2-th"><span>'+checkbox('personal-all')+'</span><b>名称</b><b>类型</b><b>来源</b><b>更新时间</b><b>解析状态</b><b>大小</b><b>操作</b></div>'+folders.map(personalFolderRow).join('')+rows.map(function(item){return personalDocRow(item.doc,item.index)}).join('')+(count?'':'<div class="pr2-doc-empty"><i>⌕</i><b>当前文件夹暂无文档</b><span>可在此新建文本、文件目录或导入文件</span></div>')+'</div><footer class="pr2-page"><span>第 1/1 页，共 '+count+' 条，已选 <b id="pr2SelectedCount">'+selectedPersonalDocs().length+'</b> 条</span><div>‹　<b>1</b>　›　<em>50 条/页⌄</em></div></footer><input class="pr2-hidden-input" id="pr2ImportFile" type="file" multiple><input class="pr2-hidden-input" id="pr2ImportFolder" type="file" webkitdirectory multiple></section>'}
function enterpriseView(){var source=enterpriseDocs[state.space]||enterpriseDocs['采购组'],folders=(enterpriseFolders[state.space]||[]).filter(function(x){return !state.query||x.toLowerCase().indexOf(state.query.toLowerCase())>-1}),rows=source.filter(function(x){return !state.query||x.name.toLowerCase().indexOf(state.query.toLowerCase())>-1}),total=state.space==='采购组'?6:source.length;return '<section class="pr2-work"><header class="pr2-title"><div><h1>'+esc(state.space)+'</h1><p>'+esc(state.space)+'</p></div></header>'+typeMenu()+'<div class="pr2-stats enterprise">'+stat('▥',total,'空间文档','blue')+stat('✓',total,'已解析文档','green')+stat('◷','2026-09-23 20:14','更新时间','orange')+stat('▧','0','待审批文档','purple')+'</div><button class="pr2-timeline" id="pr2Timeline"><b>知识时序分布 <span>（4条）</span></b><em>⌄</em></button><div class="pr2-command enterprise"><button class="outline" data-enterprise-folder-new>＋　新建文件目录</button><button class="primary" data-enterprise-import>⇧　上传文件到空间</button><button data-selection-action disabled>删除</button><button data-selection-action disabled>收藏</button><button data-selection-action disabled>授权</button><button data-selection-action disabled>解析</button><button data-selection-action disabled>添加标签</button><div class="pr2-command-spacer"></div><form id="pr2DocSearch"><input value="'+esc(state.query)+'" placeholder="搜索空间内全部文档（含子空间）"><button>⌕</button></form><button class="refresh" data-pr2-action="refresh">↻</button></div><div class="pr2-table enterprise-table"><div class="pr2-th"><span>'+checkbox('enterprise-all')+'</span><b>名称</b><b>类型</b><b>创建人</b><b>更新时间</b><b>解析状态</b><b>大小</b><b>操作</b></div>'+folders.map(function(name){return '<div class="pr2-tr pr2-folder-row"><span></span><div class="pr2-doc-name"><i class="pr2-file folder">夹</i><span><b>'+esc(name)+'</b><small>'+esc(state.space)+' / '+esc(name)+'</small></span></div><span>文件目录</span><span>sailisi</span><span>刚刚</span><span>—</span><span>—</span><div class="pr2-row-actions"><button data-enterprise-folder-open="'+esc(name)+'">打开</button></div></div>'}).join('')+rows.map(function(x){var sourceIndex=source.indexOf(x),tags=(x.tags||[]).map(function(tag){return '<em>'+esc(tag)+'</em>'}).join('');return '<div class="pr2-tr"><span>'+checkbox(x.id)+'</span><div class="pr2-doc-name">'+fileIcon(x.type)+'<span><a href="'+docHref(x.id)+'">'+esc(x.name)+'</a><small>'+tags+'<button data-enterprise-doc-tag="'+sourceIndex+'">＋ 打标</button></small></span></div><span>'+x.type+'</span><span>'+x.owner+'</span><span>'+x.updated+'</span><span class="pr2-parse">'+x.parse+'</span><span>'+x.size+'</span><div class="pr2-row-actions"><button data-pr2-action="favorite">收藏</button><button data-pr2-action="authorize">授权</button><button data-pr2-action="more">更多操作</button></div></div>'}).join('')+'</div><footer class="pr2-page"><span>第 1/1 页，共 '+(rows.length+folders.length)+' 条，已选 <b id="pr2SelectedCount">'+state.selected.size+'</b> 条</span><div>‹　<b>1</b>　›　<em>50 条/页⌄</em></div></footer></section>'}
function recycleView(){var rows=recycleDocs.filter(function(x){return !state.query||x.name.toLowerCase().indexOf(state.query.toLowerCase())>-1});return '<section class="pr2-work"><header class="pr2-title"><div><h1>回收站</h1><p>删除的个人文档将在 30 天后自动清理</p></div></header>'+typeMenu()+'<div class="pr2-command recycle"><button data-selection-action disabled>恢复</button><button data-selection-action disabled>彻底删除</button><div class="pr2-command-spacer"></div><form id="pr2DocSearch"><input value="'+esc(state.query)+'" placeholder="搜索已删除文档"><button>⌕</button></form></div><div class="pr2-table recycle-table"><div class="pr2-th"><span></span><b>名称</b><b>类型</b><b>删除时间</b><b>大小</b><b>操作</b></div>'+rows.map(function(x){return '<div class="pr2-tr"><span>'+checkbox(x.id)+'</span><div class="pr2-doc-name">'+fileIcon(x.type)+'<span><b>'+esc(x.name)+'</b></span></div><span>'+x.type+'</span><span>'+x.updated+'</span><span>'+x.size+'</span><div class="pr2-row-actions"><button data-pr2-action="restore">恢复</button><button data-pr2-action="purge">彻底删除</button></div></div>'}).join('')+'</div></section>'}
