function closeMenus(except){document.querySelectorAll('.pr2-dropdown.open').forEach(function(menu){if(menu!==except)menu.classList.remove('open')})}
function attachModal(mask){function close(){document.removeEventListener('keydown',onKey);mask.remove()}function onKey(e){if(e.key==='Escape')close()}mask.addEventListener('click',function(e){if(e.target===mask)close()});mask.querySelectorAll('[data-close]').forEach(function(btn){btn.addEventListener('click',close)});document.addEventListener('keydown',onKey);document.body.appendChild(mask);return close}
