function openAuthorizationModal(doc,initialTab){doc.authorizedUsers=doc.authorizedUsers||[];var tab=initialTab||'grant',mask=document.createElement('div');mask.className='mine-v2-modal-mask';mask.innerHTML='<section class="mine-share-modal" data-auth-resource-name="'+esc(doc.name)+'" role="dialog" aria-modal="true"><header><h2>授权</h2><button data-close>×</button></header><nav><button data-share-tab="view">查看已授权信息</button><button data-share-tab="grant">新增授权</button></nav><div class="mine-share-pane" data-share-pane="view"><div class="mine-auth-table"><div class="mine-auth-head"><b>文件名</b><b>授权用户</b><b>权限</b><b>授权时间</b><b>操作</b></div>'+(doc.authorizedUsers.length?doc.authorizedUsers.map(function(user,index){return '<div class="mine-auth-row"><span>'+fileIcon(doc.type)+'<b>'+esc(doc.name)+'</b></span><span>'+esc(user.account)+'</span><span>'+esc(user.permission)+'</span><span>'+esc(user.period)+'</span><span><button data-auth-edit>编辑</button><button data-auth-copy>复制链接</button><button data-auth-remove="'+index+'">移除</button></span></div>'}).join(''):'<div class="mine-auth-empty">当前文档暂无已授权用户</div>')+'</div></div><div class="mine-share-pane" data-share-pane="grant"><h3><i>*</i> 用户名：</h3><div class="mine-share-user-box"><div class="mine-share-filters"><select id="shareDepartment"><option>所属部门</option><option>赛力斯-采购部</option><option>赛力斯-IT部门</option></select><input id="shareUserKeyword" placeholder="工号/姓名"><button id="shareUserSearch">⌕</button><button id="shareUserReset">↻ 重置</button></div><div class="mine-share-users"><div class="mine-user-head"><label><input type="checkbox" id="shareUserAll"></label><b>工号</b><b>姓名</b><b>所属部门</b></div>'+shareUsers.map(function(user){return '<label class="mine-user-row"><input type="checkbox" data-share-user="'+esc(user.account)+'"><span>'+esc(user.account)+'</span><span>'+esc(user.name)+'</span><span><em>'+esc(user.department)+'</em></span></label>'}).join('')+'</div><footer><span>共 '+shareUsers.length+' 条</span><b>‹　<i>1</i>　›</b></footer></div><div class="mine-share-settings"><label><b><i>*</i> 权限：</b><span><input type="radio" name="sharePermission" value="查看" checked> 查看</span><span><input type="radio" name="sharePermission" value="下载+查看"> 下载+查看</span></label><label><b><i>*</i> 时间：</b><input type="date" id="shareStart" value="2026-09-29"><strong>至</strong><input type="date" id="shareEnd" value="2026-10-29"></label></div><label class="mine-share-note"><b>说明：</b><textarea id="shareNote" placeholder="请输入说明"></textarea></label></div><footer><button class="muted" id="shareClear">清空授权</button><button class="primary" id="shareConfirm">确认</button><button data-close>取消</button></footer></section>';var close=attachModal(mask);function switchTab(next){tab=next;mask.querySelectorAll('[data-share-tab]').forEach(function(btn){btn.classList.toggle('active',btn.dataset.shareTab===tab)});mask.querySelectorAll('[data-share-pane]').forEach(function(pane){pane.classList.toggle('active',pane.dataset.sharePane===tab)})}mask.querySelectorAll('[data-share-tab]').forEach(function(btn){btn.addEventListener('click',function(){switchTab(btn.dataset.shareTab)})});switchTab(tab);var all=mask.querySelector('#shareUserAll'),userBoxes=Array.prototype.slice.call(mask.querySelectorAll('[data-share-user]'));all.addEventListener('change',function(){userBoxes.forEach(function(box){box.checked=all.checked})});mask.querySelector('#shareUserSearch').addEventListener('click',function(){var word=mask.querySelector('#shareUserKeyword').value.trim().toLowerCase(),department=mask.querySelector('#shareDepartment').value;mask.querySelectorAll('.mine-user-row').forEach(function(row){var departmentMatch=department==='所属部门'||row.textContent.indexOf(department)>-1;row.style.display=departmentMatch&&(!word||row.textContent.toLowerCase().indexOf(word)>-1)?'grid':'none'})});mask.querySelector('#shareUserReset').addEventListener('click',function(){mask.querySelector('#shareUserKeyword').value='';mask.querySelector('#shareDepartment').selectedIndex=0;mask.querySelectorAll('.mine-user-row').forEach(function(row){row.style.display='grid'})});mask.querySelectorAll('[data-auth-edit]').forEach(function(btn){btn.addEventListener('click',function(){switchTab('grant')})});mask.querySelectorAll('[data-auth-copy]').forEach(function(btn){btn.addEventListener('click',function(){toast('授权链接已复制')})});mask.querySelectorAll('[data-auth-remove]').forEach(function(btn){btn.addEventListener('click',function(){doc.authorizedUsers.splice(Number(btn.dataset.authRemove),1);close();openAuthorizationModal(doc,'view');toast('已移除授权用户')})});mask.querySelector('#shareClear').addEventListener('click',function(){doc.authorizedUsers=[];toast('已清空当前文档授权')});mask.querySelector('#shareConfirm').addEventListener('click',function(){var permission=mask.querySelector('[name="sharePermission"]:checked').value,start=mask.querySelector('#shareStart').value,end=mask.querySelector('#shareEnd').value,chosen=userBoxes.filter(function(box){return box.checked}).map(function(box){return box.dataset.shareUser}),targets=doc.batchDocs||[doc];if(!chosen.length){toast('请选择需要授权的用户');return}targets.forEach(function(target){target.authorizedUsers=target.authorizedUsers||[];chosen.forEach(function(account){if(!target.authorizedUsers.some(function(item){return item.account===account}))target.authorizedUsers.push({account:account,permission:permission,period:start+' 00:00:00~'+end+' 23:59:59'})})});close();toast('已完成 '+chosen.length+' 位用户授权');render()})}
