function openDocumentBatchConfirm(title,message,confirmText,onConfirm){var mask=document.createElement('div');mask.className='mine-v2-modal-mask';mask.innerHTML='<section class="pr2-confirm-modal"><div class="pr2-confirm-icon">!</div><div><h2>'+esc(title)+'</h2><p>'+esc(message)+'</p><footer><button data-close>取消</button><button class="primary" data-doc-batch-confirm>'+esc(confirmText)+'</button></footer></div></section>';var close=attachModal(mask);mask.querySelector('[data-doc-batch-confirm]').addEventListener('click',function(){close();onConfirm()})}
function openFeishuSyncModalV2(){var authorized=false,space=state.scope==='personal'?'个人空间':state.space,mask=document.createElement('div');mask.className='mine-v2-modal-mask feishu-sync-mask';mask.innerHTML='<section class="feishu-sync-dialog"><header><div><h2>同步飞书文档</h2><p>目标位置：'+esc(space)+' · 每个用户仅能同步自己有权限访问的内容。</p></div><button data-feishu-sync-close>×</button></header><nav class="feishu-sync-steps"><span class="active"><i>1</i>用户授权</span><em>→</em><span><i>2</i>选择文档</span><em>→</em><span><i>3</i>同步到空间</span></nav><main><section class="feishu-oauth-card" data-feishu-oauth><i class="feishu-mark large">飞</i><div><b>使用飞书账号授权 Knora</b><p>授权后 Knora 获得当前用户的短期访问令牌，仅拉取该用户可访问的云文档与知识库目录；不会获得编辑权限。</p><div class="oauth-scopes"><span>读取云文档</span><span>读取云空间</span><span>读取知识库目录</span><span>离线增量同步</span></div></div><button class="primary" data-authorize-feishu>授权 access token</button></section><section class="feishu-picker" data-feishu-picker><div class="feishu-picker-head"><span><b>已授权：陈宇</b><small>访问令牌已安全保存 · 可随时撤销</small></span><button data-revoke-feishu>撤销授权</button></div><div class="feishu-picker-layout"><aside><b>我的飞书资源</b><button class="active">我的空间</button><button>我参与的知识库</button><button>与我共享</button></aside><div class="feishu-tree-picker"><label><input type="checkbox" data-feishu-item="customer-kb" checked><i>库</i><span><b>客户经营知识库</b><small>知识库 · 保留目录结构</small></span></label><div class="feishu-tree-children"><label><input type="checkbox" data-feishu-item="monthly-folder" checked><i>夹</i><span><b>月度经营分析</b><small>文件夹 · 12 项内容</small></span></label><label><input type="checkbox" data-feishu-item="report"><i>文</i><span><b>2026 年重点客户经营分析报告</b><small>飞书文档 · 今天更新</small></span></label></div><label><input type="checkbox" data-feishu-item="channel-kb"><i>库</i><span><b>渠道运营知识库</b><small>知识库 · 28 项内容</small></span></label><label><input type="checkbox" data-feishu-item="collab"><i>文</i><span><b>客户风险处置协同记录</b><small>飞书多维表格 · 仅同步为只读文档快照</small></span></label></div></div><div class="feishu-sync-options"><label><input type="checkbox" checked> 保留飞书知识库与文件夹目录结构</label><label><input type="checkbox" checked> 每 30 分钟增量同步</label><label><input type="checkbox" checked> 源文档无权限后自动停止展示</label></div></section></main><footer><button data-feishu-sync-close>取消</button><button class="primary" data-feishu-sync-submit disabled>开始同步</button></footer></section>';function close(){mask.remove()}mask.querySelectorAll('[data-feishu-sync-close]').forEach(function(button){button.addEventListener('click',close)});mask.addEventListener('click',function(event){if(event.target===mask)close()});mask.querySelector('[data-authorize-feishu]').addEventListener('click',function(){authorized=true;mask.querySelector('[data-feishu-oauth]').classList.add('authorized');mask.querySelector('[data-feishu-picker]').classList.add('show');mask.querySelectorAll('.feishu-sync-steps span').forEach(function(node){node.classList.add('active')});mask.querySelector('[data-feishu-sync-submit]').disabled=false;toast('飞书用户授权成功，access token 已安全保存')});mask.querySelector('[data-revoke-feishu]').addEventListener('click',function(){authorized=false;mask.querySelector('[data-feishu-oauth]').classList.remove('authorized');mask.querySelector('[data-feishu-picker]').classList.remove('show');mask.querySelector('[data-feishu-sync-submit]').disabled=true;toast('已撤销本次飞书授权')});mask.querySelector('[data-feishu-sync-submit]').addEventListener('click',function(){if(!authorized){toast('请先完成飞书用户授权');return}var checked=Array.prototype.slice.call(mask.querySelectorAll('[data-feishu-item]:checked'));if(!checked.length){toast('请先选择要同步的飞书内容');return}var target=state.scope==='personal'?personalDocs:(enterpriseDocs[state.space]||enterpriseDocs['采购组']),selectedKeys=checked.map(function(input){return input.dataset.feishuItem}),selectedDocs=[];if(selectedKeys.some(function(key){return key==='customer-kb'||key==='monthly-folder'||key==='report'}))selectedDocs.push({id:'doc-feishu-report',name:'2026 年重点客户经营分析报告'});if(selectedKeys.indexOf('channel-kb')>-1)selectedDocs.push({id:'doc-feishu-wiki',name:'渠道运营知识库同步内容'});if(selectedKeys.indexOf('collab')>-1)selectedDocs.push({id:'doc-feishu-collab',name:'客户风险处置协同记录'});selectedDocs.forEach(function(item){if(!target.some(function(doc){return doc.id===item.id}))target.push({id:item.id,name:item.name,type:'DOCX',owner:'陈宇',updated:'刚刚',parse:'解析成功',size:'—',tags:['飞书同步'],sourceType:'飞书同步',folder:state.scope==='personal'?state.personalFolder:state.enterpriseFolder,authorizedUsers:[]})});close();render();toast('同步已开始，所选内容将进入“'+space+'”当前文档目录')});document.body.appendChild(mask)}
function selectedEnterpriseDocs(){var source=enterpriseDocs[state.space]||enterpriseDocs['采购组'];return Array.from(state.selected).filter(function(key){return /^enterprise-doc-\d+$/.test(key)}).map(function(key){return source[Number(key.split('-').pop())]}).filter(Boolean)}
function enterpriseBatchDoc(){var docs=selectedEnterpriseDocs();return docs.length===1?docs[0]:{name:'已选择 '+docs.length+' 个文档',type:'DOCX',tags:docs[0]?(docs[0].tags||[]):[],authorizedUsers:[],batchDocs:docs}}
var bindEnterpriseResourceActionsBase=bindEnterpriseResourceActions;
bindEnterpriseResourceActions=function(){
 bindEnterpriseResourceActionsBase();if(state.scope!=='enterprise')return;
 var toolbar=document.querySelector('.pr2-command.enterprise');if(!toolbar)return;
 var actions=['remove','favorite','authorize','parse','tag'],buttons=Array.prototype.slice.call(toolbar.querySelectorAll('[data-selection-action]'));
 buttons.forEach(function(button,index){button.dataset.enterpriseBatch=actions[index]||''});
 var move=document.createElement('button');move.textContent='移动';move.dataset.selectionAction='';move.dataset.enterpriseBatch='move';move.disabled=true;var spacer=toolbar.querySelector('.pr2-command-spacer');toolbar.insertBefore(move,spacer);
 updateSelection();
 toolbar.querySelectorAll('[data-enterprise-batch]').forEach(function(button){button.addEventListener('click',function(){
  if(button.disabled)return;var docs=selectedEnterpriseDocs(),op=button.dataset.enterpriseBatch;if(!docs.length){toast('请选择文档');return}
  if(op==='authorize')openPublicDocumentAuthorization(enterpriseBatchDoc());
  if(op==='tag')openTagModal(enterpriseBatchDoc());
  if(op==='favorite'){docs.forEach(function(doc){doc.star=true});state.selected.clear();render();toast('已收藏 '+docs.length+' 个文档')}
  if(op==='parse'){docs.forEach(function(doc){doc.parse='解析中'});state.selected.clear();render();toast('已提交 '+docs.length+' 个文档的解析任务')}
  if(op==='move')openEnterpriseMoveModal('已选择 '+docs.length+' 个文档','doc',function(target){docs.forEach(function(doc){doc.folder=target});state.selected.clear()});
  if(op==='remove')openDocumentBatchConfirm('从当前空间中删除所选文档？','将 '+docs.length+' 个文档从 '+state.space+' 的资源目录中移除。','确认删除',function(){var source=enterpriseDocs[state.space]||enterpriseDocs['采购组'];enterpriseDocs[state.space]=source.filter(function(doc){return docs.indexOf(doc)<0});state.selected.clear();render();toast('已从当前空间移除 '+docs.length+' 个文档')})
 })})
};
document.addEventListener('click',function(event){
 var feishuSync=event.target.closest('[data-open-feishu-sync]');if(feishuSync){event.preventDefault();event.stopImmediatePropagation();openFeishuSyncModalV2();return}
 var batch=event.target.closest('[data-batch-more]');if(batch){event.preventDefault();event.stopImmediatePropagation();closeMenus();var docs=selectedPersonalDocs(),op=batch.dataset.batchMore;if(!docs.length){toast('请选择文档');return}if(op==='move')openMoveModal(batchDoc());if(op==='download')toast('已开始打包下载 '+docs.length+' 个文档');if(op==='delete')openDocumentBatchConfirm('删除所选文档？','所选 '+docs.length+' 个文档将移入回收站，可在 30 天内恢复。','确认删除',function(){docs.forEach(function(doc){recycleDocs.push({id:doc.id,name:doc.name,type:doc.type,updated:'刚刚',size:doc.size})});for(var i=personalDocs.length-1;i>=0;i--)if(docs.indexOf(personalDocs[i])>-1)personalDocs.splice(i,1);state.selected.clear();render();toast('已将 '+docs.length+' 个文档移入回收站')});return}
 var single=event.target.closest('[data-enterprise-doc-delete]');if(single){event.preventDefault();event.stopImmediatePropagation();if(!canManagePublicSpace())return;var source=enterpriseDocs[state.space]||enterpriseDocs['采购组'],index=Number(single.dataset.enterpriseDocDelete),doc=source[index];if(!doc)return;openDocumentBatchConfirm('从当前空间中删除文档？','将“'+doc.name+'”从 '+state.space+' 的资源目录中移除。','确认删除',function(){source.splice(index,1);render();toast('已从当前空间移除文档')})}
},true);
restoreMetadataUploads();render();
window.addEventListener('knora:tenantchange',function(event){var next=event.detail&&event.detail.root?event.detail.root:resourceTenantRoot(),old=resourceRootName;if(next===old)return;resourceRootName=next;enterpriseDocs[next]=enterpriseDocs[old]||enterpriseDocs['赛力斯企业空间'];if(state.space===old)state.space=next;personalDocs=personalDocs.filter(function(d){return !/^personal-upload-/.test(d.id)});Object.keys(enterpriseDocs).forEach(function(space){enterpriseDocs[space]=enterpriseDocs[space].filter(function(d){return !/^enterprise-upload-/.test(d.id)})});restoreMetadataUploads();render()});
